scripts.script:
local LMG2L = {};

LMG2L["ScreenGui_1"] = Instance.new("ScreenGui", game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"));
LMG2L["ScreenGui_1"].ZIndexBehavior = Enum.ZIndexBehavior.Sibling;

LMG2L["Frame_2"] = Instance.new("Frame", LMG2L["ScreenGui_1"]);
LMG2L["Frame_2"].BorderSizePixel = 0;
LMG2L["Frame_2"].BackgroundColor3 = Color3.fromRGB(60, 60, 60);
LMG2L["Frame_2"].Size = UDim2.new(0, 650, 0, 350);
LMG2L["Frame_2"].Position = UDim2.new(0, 150, 0, 50);

LMG2L["UICorner_3"] = Instance.new("UICorner", LMG2L["Frame_2"]);
LMG2L["UICorner_3"].CornerRadius = UDim.new(0, 12);

LMG2L["TextLabel_5"] = Instance.new("TextLabel", LMG2L["Frame_2"]);
LMG2L["TextLabel_5"].BorderSizePixel = 0;
LMG2L["TextLabel_5"].TextSize = 32;
LMG2L["TextLabel_5"].BackgroundColor3 = Color3.fromRGB(202, 202, 202);
LMG2L["TextLabel_5"].Font = Enum.Font.SourceSans;
LMG2L["TextLabel_5"].Size = UDim2.new(0, 630, 0, 28);
LMG2L["TextLabel_5"].Text = "Team loopkidd join today!";
LMG2L["TextLabel_5"].Position = UDim2.new(0, 10, 0, 8);

LMG2L["UICorner_6"] = Instance.new("UICorner", LMG2L["TextLabel_5"]);
LMG2L["UICorner_6"].CornerRadius = UDim.new(0, 12);

LMG2L["TextBox_7"] = Instance.new("TextBox", LMG2L["Frame_2"]);
LMG2L["TextBox_7"].TextXAlignment = Enum.TextXAlignment.Left;
LMG2L["TextBox_7"].TextYAlignment = Enum.TextYAlignment.Top;
LMG2L["TextBox_7"].BackgroundColor3 = Color3.fromRGB(40, 42, 54);
LMG2L["TextBox_7"].TextColor3 = Color3.fromRGB(248, 248, 242);
LMG2L["TextBox_7"].Font = Enum.Font.Code;
LMG2L["TextBox_7"].TextSize = 18;
LMG2L["TextBox_7"].Size = UDim2.new(0, 630, 0, 240);
LMG2L["TextBox_7"].Position = UDim2.new(0, 10, 0, 44);
LMG2L["TextBox_7"].ClearTextOnFocus = false;
LMG2L["TextBox_7"].Text = [[local x = 10
print(x)]]

LMG2L["UICorner_8"] = Instance.new("UICorner", LMG2L["TextBox_7"]);
LMG2L["UICorner_8"].CornerRadius = UDim.new(0, 6);

LMG2L["TextButton_9"] = Instance.new("TextButton", LMG2L["Frame_2"]);
LMG2L["TextButton_9"].BorderSizePixel = 0;
LMG2L["TextButton_9"].BackgroundColor3 = Color3.fromRGB(98, 156, 255);
LMG2L["TextButton_9"].Size = UDim2.new(0, 120, 0, 40);
LMG2L["TextButton_9"].Text = "execute";
LMG2L["TextButton_9"].Position = UDim2.new(0, 10, 0, 300);

LMG2L["TextButton_a"] = Instance.new("TextButton", LMG2L["Frame_2"]);
LMG2L["TextButton_a"].BorderSizePixel = 0;
LMG2L["TextButton_a"].BackgroundColor3 = Color3.fromRGB(255, 95, 95);
LMG2L["TextButton_a"].Size = UDim2.new(0, 120, 0, 40);
LMG2L["TextButton_a"].Text = "clear";
LMG2L["TextButton_a"].Position = UDim2.new(0, 520, 0, 300);

LMG2L["Frame_2"].Active = true
LMG2L["Frame_2"].Draggable = true

local textBox = LMG2L["TextBox_7"]

LMG2L["TextButton_9"].MouseButton1Click:Connect(function()
	local func, err = loadstring(textBox.Text)
	if func then
		pcall(func)
	end
end)

LMG2L["TextButton_a"].MouseButton1Click:Connect(function()
	textBox.Text = ""
end)

textBox:GetPropertyChangedSignal("Text"):Connect(function()
	local newText = textBox.Text
	newText = newText:gsub("local", "<font color='rgb(255,0,0)'>local</font>")
	textBox.Text = newText
end)

return LMG2L["ScreenGui_1"], require
